package studio.limen.auth;
import com.google.gson.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.security.spec.*;
public final class AuthWire {
 public static final String CHANNEL="limen:auth";public static final Gson JSON=new Gson();
 private AuthWire(){}
 public static byte[] sign(String secret,JsonObject body)throws GeneralSecurityException{String payload=JSON.toJson(body);long time=System.currentTimeMillis();JsonObject out=new JsonObject();out.addProperty("time",time);out.addProperty("body",payload);out.addProperty("mac",Base64.getEncoder().encodeToString(mac(secret,time+"."+payload)));return JSON.toJson(out).getBytes(StandardCharsets.UTF_8);}
 public static JsonObject verify(String secret,byte[] bytes)throws GeneralSecurityException{if(bytes.length>8192)throw new GeneralSecurityException("Size");try{JsonObject env=JsonParser.parseString(new String(bytes,StandardCharsets.UTF_8)).getAsJsonObject();long time=env.get("time").getAsLong();if(time<System.currentTimeMillis()-15000||time>System.currentTimeMillis()+15000)throw new GeneralSecurityException("Expired");String body=env.get("body").getAsString();if(!MessageDigest.isEqual(mac(secret,time+"."+body),Base64.getDecoder().decode(env.get("mac").getAsString())))throw new GeneralSecurityException("Signature");return JsonParser.parseString(body).getAsJsonObject();}catch(RuntimeException e){throw new GeneralSecurityException("Invalid packet");}}
 private static byte[] mac(String key,String body)throws GeneralSecurityException{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(key.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return m.doFinal(body.getBytes(StandardCharsets.UTF_8));}
 public static String nonce(){byte[] n=new byte[32];new SecureRandom().nextBytes(n);return Base64.getUrlEncoder().withoutPadding().encodeToString(n);}
 public static final OAEPParameterSpec OAEP=new OAEPParameterSpec("SHA-256","MGF1",MGF1ParameterSpec.SHA256,PSource.PSpecified.DEFAULT);
 public static JsonObject seal(PublicKey key,String token,char[] password,boolean register)throws GeneralSecurityException{byte[] aes=new byte[32],iv=new byte[12];new SecureRandom().nextBytes(aes);new SecureRandom().nextBytes(iv);try{JsonObject body=new JsonObject();body.addProperty("password",new String(password));body.addProperty("register",register);Cipher gcm=Cipher.getInstance("AES/GCM/NoPadding");gcm.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(aes,"AES"),new GCMParameterSpec(128,iv));gcm.updateAAD(token.getBytes(StandardCharsets.UTF_8));byte[] ciphertext=gcm.doFinal(JSON.toJson(body).getBytes(StandardCharsets.UTF_8));Cipher rsa=Cipher.getInstance("RSA/ECB/OAEPPadding");rsa.init(Cipher.ENCRYPT_MODE,key,OAEP);JsonObject out=new JsonObject();out.addProperty("sealedKey",Base64.getEncoder().encodeToString(rsa.doFinal(aes)));out.addProperty("iv",Base64.getEncoder().encodeToString(iv));out.addProperty("ciphertext",Base64.getEncoder().encodeToString(ciphertext));return out;}finally{Arrays.fill(aes,(byte)0);}}
 public static JsonObject open(PrivateKey key,String token,JsonObject sealed)throws GeneralSecurityException{byte[] aes=null;try{byte[] wrap=Base64.getDecoder().decode(sealed.get("sealedKey").getAsString()),iv=Base64.getDecoder().decode(sealed.get("iv").getAsString()),data=Base64.getDecoder().decode(sealed.get("ciphertext").getAsString());if(wrap.length!=384||iv.length!=12||data.length>2048)throw new GeneralSecurityException("Size");Cipher rsa=Cipher.getInstance("RSA/ECB/OAEPPadding");rsa.init(Cipher.DECRYPT_MODE,key,OAEP);aes=rsa.doFinal(wrap);if(aes.length!=32)throw new GeneralSecurityException("Key");Cipher gcm=Cipher.getInstance("AES/GCM/NoPadding");gcm.init(Cipher.DECRYPT_MODE,new SecretKeySpec(aes,"AES"),new GCMParameterSpec(128,iv));gcm.updateAAD(token.getBytes(StandardCharsets.UTF_8));byte[] plain=gcm.doFinal(data);try{return JsonParser.parseString(new String(plain,StandardCharsets.UTF_8)).getAsJsonObject();}finally{Arrays.fill(plain,(byte)0);}}catch(RuntimeException e){throw new GeneralSecurityException("Envelope");}finally{if(aes!=null)Arrays.fill(aes,(byte)0);}}
}
